import"./chunk-VC46IEJQ.js";var e=(n,s)=>({en:n,zh:s}),a=(n,s,d,l,i,h,y,f,w,m,u={})=>({id:n,names:e(s,d),region:"riverlands",...l?{seat:l}:{},tier:i,liege:h,sigil:y,colors:f,summary:w,refs:m,...u}),r=(n,s,d,l={})=>({id:n,name:e(s,d),...l}),o=e("Arms not described in the main novels","\u6B63\u4F20\u4E2D\u672A\u63CF\u8FF0\u5176\u7EB9\u7AE0"),t=["#8a8f96","#3c4046"],g={group:"riverlands",houses:[a("tully","House Tully","\u5F92\u5229\u5BB6\u65CF","riverrun","great",null,e("A leaping silver trout on a field of rippling blue and red","\u7EA2\u84DD\u6CE2\u7EB9\u5E95\u4E0A\u4E00\u6761\u8DC3\u8D77\u7684\u94F6\u8272\u9CDF\u9C7C"),["#2f5d93","#c9ced6"],e("Lords Paramount of the Trident, ruling the riverlands from Riverrun since Aegon the Conqueror raised them over the other river lords. They are an old Andal-descended house, more respected than feared, and their marriages bind them to the Starks and the Arryns.","\u4E09\u53C9\u621F\u6CB3\u6700\u9AD8\u7EDF\u9886\uFF0C\u81EA\u5F81\u670D\u8005\u4F0A\u803F\u5C06\u5176\u64E2\u5347\u4E8E\u8BF8\u6CB3\u95F4\u9886\u4E3B\u4E4B\u4E0A\u8D77\uFF0C\u4FBF\u5750\u9547\u5954\u6D41\u57CE\u7EDF\u6CBB\u6CB3\u95F4\u5730\u3002\u5F92\u5229\u5BB6\u662F\u5B89\u8FBE\u5C14\u8840\u7EDF\u7684\u53E4\u8001\u5BB6\u65CF\uFF0C\u53D7\u4EBA\u656C\u91CD\u591A\u4E8E\u4EE4\u4EBA\u754F\u60E7\uFF0C\u5176\u8054\u59FB\u4F7F\u4E4B\u4E0E\u53F2\u5854\u514B\u3001\u827E\u6797\u4E24\u5BB6\u7D27\u7D27\u76F8\u8FDE\u3002"),["agot","asos","twoiaf"],{words:e("Family, Duty, Honor","\u5BB6\u65CF\u3001\u8D23\u4EFB\u3001\u8363\u8A89"),members:[r("hoster-tully","Hoster Tully","\u970D\u65AF\u7279\xB7\u5F92\u5229",{spouses:["minisa-whent"],note:e("Lord of Riverrun; bedridden and dying when the war begins.","\u5954\u6D41\u57CE\u516C\u7235\uFF1B\u6218\u4E89\u7206\u53D1\u65F6\u5DF2\u5367\u75C5\u4E0D\u8D77\u3002"),fate:e("Dies at Riverrun early in A Storm of Swords and is given a river funeral.","\u5728\u300A\u51B0\u96E8\u7684\u98CE\u66B4\u300B\u5F00\u5934\u6B7B\u4E8E\u5954\u6D41\u57CE\uFF0C\u4EE5\u6CB3\u846C\u9001\u522B\u3002")}),r("brynden-tully","Brynden Tully","\u5E03\u6797\u767B\xB7\u5F92\u5229",{note:e(`"The Blackfish", Hoster's younger brother; a famed knight who never married. Their father is not named in the novels.`,"\u4EBA\u79F0\u201C\u9ED1\u9C7C\u201D\uFF0C\u970D\u65AF\u7279\u4E4B\u5F1F\uFF0C\u7EC8\u8EAB\u672A\u5A36\u7684\u8457\u540D\u9A91\u58EB\u3002\u5144\u5F1F\u4E8C\u4EBA\u4E4B\u7236\u5728\u5C0F\u8BF4\u4E2D\u672A\u5177\u540D\u3002"),fate:e("Holds Riverrun against the Lannisters and escapes when it is surrendered.","\u4E3A\u5BF9\u6297\u5170\u5C3C\u65AF\u7279\u5BB6\u6B7B\u5B88\u5954\u6D41\u57CE\uFF0C\u57CE\u7834\u65F6\u6210\u529F\u8131\u8EAB\u3002")}),r("catelyn-tully","Catelyn Tully","\u51EF\u7279\u7433\xB7\u5F92\u5229",{father:"hoster-tully",mother:"minisa-whent",spouses:["eddard-stark"],note:e("Hoster's elder daughter; Lady of Winterfell.","\u970D\u65AF\u7279\u7684\u957F\u5973\uFF0C\u4E34\u51AC\u57CE\u592B\u4EBA\u3002"),fate:e("Murdered at the Red Wedding; her body is later raised as Lady Stoneheart, who leads the brotherhood without banners.","\u6B7B\u4E8E\u8840\u8272\u5A5A\u793C\uFF1B\u9057\u4F53\u540E\u88AB\u590D\u6D3B\u4E3A\u201C\u77F3\u5FC3\u592B\u4EBA\u201D\uFF0C\u9886\u5BFC\u65E0\u65D7\u5144\u5F1F\u4F1A\u3002")}),r("lysa-tully","Lysa Tully","\u83B1\u838E\xB7\u5F92\u5229",{father:"hoster-tully",mother:"minisa-whent",spouses:["jon-arryn"],note:e("Hoster's younger daughter; widow of Jon Arryn and mother of Robert Arryn.","\u970D\u65AF\u7279\u7684\u6B21\u5973\uFF0C\u743C\u6069\xB7\u827E\u6797\u7684\u9057\u5B40\uFF0C\u52B3\u52C3\xB7\u827E\u6797\u4E4B\u6BCD\u3002"),fate:e("Marries Petyr Baelish and is pushed by him through the Moon Door.","\u5AC1\u7ED9\u57F9\u63D0\u5C14\xB7\u8D1D\u91CC\u5E2D\uFF0C\u540E\u88AB\u4ED6\u63A8\u51FA\u6708\u95E8\u3002")}),r("edmure-tully","Edmure Tully","\u827E\u5FB7\u6155\xB7\u5F92\u5229",{father:"hoster-tully",mother:"minisa-whent",note:e("Hoster's only son and heir; brave but rash.","\u970D\u65AF\u7279\u552F\u4E00\u7684\u513F\u5B50\u4E0E\u7EE7\u627F\u4EBA\uFF0C\u52C7\u6562\u5374\u51B2\u52A8\u3002"),fate:e("Weds Roslin Frey at the Twins, is taken captive at the Red Wedding, and later surrenders Riverrun to Jaime.","\u5728\u5B6A\u6CB3\u57CE\u8FCE\u5A36\u841D\u4E1D\u7433\xB7\u4F5B\u96F7\uFF0C\u8840\u8272\u5A5A\u793C\u4E0A\u88AB\u4FD8\uFF0C\u540E\u5411\u8A79\u59C6\u732E\u51FA\u5954\u6D41\u57CE\u3002")})]}),a("frey","House Frey","\u4F5B\u96F7\u5BB6\u65CF","the-twins","major","tully",e("Two grey towers joined by a bridge above blue water, on a silver-grey field","\u94F6\u7070\u5E95\u4E0A\uFF0C\u4E24\u5EA7\u7070\u8272\u5854\u697C\u4EE5\u6865\u76F8\u8FDE\uFF0C\u4E0B\u6709\u84DD\u8272\u6CB3\u6C34"),["#8d96a1","#355b8c"],e("Lords of the Crossing, a comparatively young house that built the Twins over the Green Fork and grew rich on its tolls. Old Lord Walder has fathered a vast brood, and the house is known for slow loyalty and long grudges.","\u6E21\u53E3\u9886\u4E3B\uFF0C\u4E00\u4E2A\u76F8\u5BF9\u5E74\u8F7B\u7684\u5BB6\u65CF\uFF0C\u5728\u7EFF\u53C9\u6CB3\u4E0A\u5EFA\u8D77\u5B6A\u6CB3\u57CE\uFF0C\u9760\u6536\u53D6\u8FC7\u8DEF\u8D39\u81F4\u5BCC\u3002\u8001\u74E6\u5FB7\u4FAF\u7235\u5B50\u5B59\u6210\u7FA4\uFF0C\u8FD9\u4E2A\u5BB6\u65CF\u4EE5\u6548\u5FE0\u8FDF\u7F13\u3001\u775A\u7726\u5FC5\u62A5\u8457\u79F0\u3002"),["agot","asos","affc","twoiaf"],{members:[r("perra-royce","Perra Royce","\u4F69\u62C9\xB7\u7F57\u4F0A\u65AF",{note:e("Born a Royce; Walder Frey's first wife.","\u51FA\u8EAB\u7F57\u4F0A\u65AF\u5BB6\u65CF\uFF0C\u74E6\u5FB7\xB7\u4F5B\u96F7\u7684\u7B2C\u4E00\u4EFB\u59BB\u5B50\u3002")}),r("cyrenna-swann","Cyrenna Swann","\u8D5B\u4F26\u5A1C\xB7\u53F2\u6587",{note:e("Born a Swann; Walder Frey's second wife.","\u51FA\u8EAB\u53F2\u6587\u5BB6\u65CF\uFF0C\u74E6\u5FB7\xB7\u4F5B\u96F7\u7684\u7B2C\u4E8C\u4EFB\u59BB\u5B50\u3002")}),r("amarei-crakehall","Amarei Crakehall","\u963F\u739B\u857E\xB7\u514B\u96F7\u8D6B",{note:e("Born a Crakehall; Walder Frey's third wife.","\u51FA\u8EAB\u514B\u96F7\u8D6B\u5BB6\u65CF\uFF0C\u74E6\u5FB7\xB7\u4F5B\u96F7\u7684\u7B2C\u4E09\u4EFB\u59BB\u5B50\u3002")}),r("annara-farring","Annara Farring","\u5B89\u5A1C\u62C9\xB7\u6CD5\u6797",{note:e("Born a Farring; one of Walder Frey's wives.","\u51FA\u8EAB\u6CD5\u6797\u5BB6\u65CF\uFF0C\u74E6\u5FB7\xB7\u4F5B\u96F7\u7684\u59BB\u5B50\u4E4B\u4E00\u3002")}),r("joyeuse-erenford","Joyeuse Erenford","\u4E54\u4F0A\u4E1D\xB7\u827E\u4F26\u798F\u5FB7",{note:e("Born an Erenford; Walder Frey's young eighth wife.","\u51FA\u8EAB\u827E\u4F26\u798F\u5FB7\u5BB6\u65CF\uFF0C\u74E6\u5FB7\xB7\u4F5B\u96F7\u5E74\u8F7B\u7684\u7B2C\u516B\u4EFB\u59BB\u5B50\u3002")}),r("walder-frey","Walder Frey","\u74E6\u5FB7\xB7\u4F5B\u96F7",{spouses:["perra-royce","cyrenna-swann","amarei-crakehall","alyssa-blackwood","sarya-whent","bethany-rosby","annara-farring","joyeuse-erenford"],note:e("Lord of the Crossing, past ninety; married eight times.","\u6E21\u53E3\u9886\u4E3B\uFF0C\u5E74\u903E\u4E5D\u65EC\uFF0C\u5148\u540E\u516B\u5EA6\u5A36\u59BB\u3002"),fate:e("Plans the Red Wedding with Tywin Lannister and Roose Bolton.","\u4E0E\u6CF0\u6E29\xB7\u5170\u5C3C\u65AF\u7279\u548C\u5362\u65AF\xB7\u6CE2\u987F\u5408\u8C0B\u7B56\u5212\u8840\u8272\u5A5A\u793C\u3002")}),r("stevron-frey","Stevron Frey","\u53F2\u63D0\u592B\u4F26\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"perra-royce",note:e("Eldest son and heir, himself an old man.","\u957F\u5B50\u53CA\u7EE7\u627F\u4EBA\uFF0C\u81EA\u5DF1\u4E5F\u5DF2\u5E74\u8FC8\u3002"),fate:e("Dies in the westerlands soon after Robb's victory at Oxcross.","\u7F57\u67CF\u8D62\u5F97\u725B\u6D25\u4E4B\u6218\u540E\u4E0D\u4E45\u6B7B\u4E8E\u897F\u5883\u3002")}),r("emmon-frey","Emmon Frey","\u827E\u8499\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"perra-royce",spouses:["genna-lannister"],note:e("Second son; husband of Genna Lannister.","\u6B21\u5B50\uFF0C\u5409\u5A1C\xB7\u5170\u5C3C\u65AF\u7279\u7684\u4E08\u592B\u3002")}),r("aenys-frey","Aenys Frey","\u4F0A\u5C3C\u65AF\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"perra-royce",note:e("Third son.","\u4E09\u5B50\u3002")}),r("perriane-frey","Perriane Frey","\u4F69\u4E3D\u5B89\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"perra-royce",note:e("Eldest daughter.","\u957F\u5973\u3002")}),r("jared-frey","Jared Frey","\u6770\u745E\u5FB7\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"cyrenna-swann",note:e("Son of the second wife.","\u7B2C\u4E8C\u4EFB\u59BB\u5B50\u6240\u751F\u4E4B\u5B50\u3002"),fate:e("Goes missing at White Harbor in A Dance with Dragons.","\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\u5728\u767D\u6E2F\u5931\u8E2A\u3002")}),r("luceon-frey","Luceon Frey","\u5362\u897F\u6602\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"cyrenna-swann",note:e("A septon.","\u4E00\u540D\u4FEE\u58EB\u3002")}),r("hosteen-frey","Hosteen Frey","\u970D\u65AF\u4E01\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"amarei-crakehall",note:e("A strong, hot-tempered knight.","\u5F3A\u58EE\u800C\u66B4\u8E81\u7684\u9A91\u58EB\u3002")}),r("lythene-frey","Lythene Frey","\u8389\u745F\u59AE\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"amarei-crakehall",note:e("Daughter of the third wife.","\u7B2C\u4E09\u4EFB\u59BB\u5B50\u6240\u751F\u4E4B\u5973\u3002")}),r("symond-frey","Symond Frey","\u8D5B\u8499\u5FB7\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"amarei-crakehall",note:e("Counts coins for the house.","\u4E3A\u5BB6\u65CF\u7BA1\u94B1\u3002")}),r("danwell-frey","Danwell Frey","\u4E39\u5A01\u5C14\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"amarei-crakehall",note:e("A knight.","\u9A91\u58EB\u3002")}),r("merrett-frey","Merrett Frey","\u6885\u91CC\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"amarei-crakehall",spouses:["mariya-darry"],note:e("A drunkard with an unlucky life.","\u4E00\u751F\u4E0D\u5F97\u5FD7\u7684\u9152\u9B3C\u3002"),fate:e("Hanged by the brotherhood without banners after the Red Wedding.","\u8840\u8272\u5A5A\u793C\u540E\u88AB\u65E0\u65D7\u5144\u5F1F\u4F1A\u540A\u6B7B\u3002")}),r("geremy-frey","Geremy Frey","\u6770\u745E\u7C73\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"amarei-crakehall",note:e("Drowned before the main story.","\u6545\u4E8B\u5F00\u59CB\u524D\u6EBA\u4EA1\u3002")}),r("raymund-frey","Raymund Frey","\u96F7\u8499\u5FB7\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"amarei-crakehall",note:e("A knight.","\u9A91\u58EB\u3002")}),r("lothar-frey","Lothar Frey","\u7F57\u7D22\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"alyssa-blackwood",note:e(`"Lame Lothar", the family's steward and schemer.`,"\u4EBA\u79F0\u201C\u8DDB\u5B50\u7F57\u7D22\u201D\uFF0C\u5BB6\u65CF\u7684\u603B\u7BA1\u4E0E\u8C0B\u58EB\u3002"),fate:e("Helps stage the Red Wedding.","\u53C2\u4E0E\u5E03\u7F6E\u8840\u8272\u5A5A\u793C\u3002")}),r("jammos-frey","Jammos Frey","\u8A79\u59C6\u65AF\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"alyssa-blackwood",note:e("Father of Big Walder.","\u201C\u5927\u74E6\u5FB7\u201D\u4E4B\u7236\u3002")}),r("whalen-frey","Whalen Frey","\u5A01\u4F26\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"alyssa-blackwood",note:e("A knight.","\u9A91\u58EB\u3002")}),r("morya-frey","Morya Frey","\u83AB\u96C5\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"alyssa-blackwood",note:e("Daughter of the fourth wife.","\u7B2C\u56DB\u4EFB\u59BB\u5B50\u6240\u751F\u4E4B\u5973\u3002")}),r("tyta-frey","Tyta Frey","\u7F07\u5854\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"alyssa-blackwood",note:e('"Tyta the Maid", unmarried.',"\u4EBA\u79F0\u201C\u5904\u5973\u7F07\u5854\u201D\uFF0C\u672A\u5A5A\u3002")}),r("perwyn-frey","Perwyn Frey","\u6D3E\u6E29\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"bethany-rosby",note:e("Escorts Catelyn to Bitterbridge.","\u66FE\u62A4\u9001\u51EF\u7279\u7433\u524D\u5F80\u82E6\u6865\u3002")}),r("benfrey-frey","Benfrey Frey","\u73ED\u5F17\u96F7\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"bethany-rosby",note:e("A knight.","\u9A91\u58EB\u3002"),fate:e("Dies of a wound taken at the Red Wedding.","\u6B7B\u4E8E\u8840\u8272\u5A5A\u793C\u4E0A\u53D7\u7684\u4F24\u3002")}),r("willamen-frey","Willamen Frey","\u5A01\u62C9\u66FC\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"bethany-rosby",note:e("A maester.","\u4E00\u540D\u5B66\u58EB\u3002")}),r("olyvar-frey","Olyvar Frey","\u5965\u5229\u6CD5\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"bethany-rosby",note:e("Robb Stark's loyal squire.","\u7F57\u67CF\xB7\u53F2\u5854\u514B\u5FE0\u5FC3\u7684\u4F8D\u4ECE\u3002")}),r("roslin-frey","Roslin Frey","\u841D\u4E1D\u7433\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"bethany-rosby",note:e("A gentle, pretty daughter of the sixth wife.","\u7B2C\u516D\u4EFB\u59BB\u5B50\u6240\u751F\u3001\u6E29\u67D4\u7F8E\u4E3D\u7684\u5973\u513F\u3002"),fate:e("Marries Edmure Tully at the Twins on the night of the Red Wedding, and is with child by him.","\u5728\u8840\u8272\u5A5A\u793C\u5F53\u665A\u4E8E\u5B6A\u6CB3\u57CE\u5AC1\u7ED9\u827E\u5FB7\u6155\xB7\u5F92\u5229\uFF0C\u5E76\u6000\u4E0A\u4E86\u4ED6\u7684\u5B69\u5B50\u3002")}),r("arwaya-frey","Arwaya Frey","\u827E\u74E6\u96C5\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"annara-farring",note:e("Daughter of the seventh wife.","\u7B2C\u4E03\u4EFB\u59BB\u5B50\u6240\u751F\u4E4B\u5973\u3002")}),r("wendel-frey","Wendel Frey","\u6E29\u5FB7\u5C14\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"annara-farring",note:e("Fostered at Seagard.","\u5728\u6D77\u7586\u57CE\u53D7\u517B\u3002")}),r("colmar-frey","Colmar Frey","\u67EF\u5C14\u9A6C\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"annara-farring",note:e("Promised to the Faith.","\u5DF2\u8BB8\u8EAB\u4E8E\u4E03\u795E\u4FE1\u4EF0\u3002")}),r("waltyr-frey","Waltyr Frey","\u74E6\u63D0\u5C14\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"annara-farring",note:e("Called Tyr.","\u4EBA\u79F0\u201C\u63D0\u5C14\u201D\u3002")}),r("elmar-frey","Elmar Frey","\u827E\u9A6C\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"annara-farring",note:e("Once betrothed to Arya Stark under Robb's bargain.","\u4F9D\u7F57\u67CF\u7684\u7EA6\u5B9A\uFF0C\u66FE\u4E0E\u827E\u8389\u4E9A\xB7\u53F2\u5854\u514B\u8BA2\u5A5A\u3002")}),r("shirei-frey","Shirei Frey","\u96EA\u857E\xB7\u4F5B\u96F7",{father:"walder-frey",mother:"annara-farring",note:e("Youngest trueborn child.","\u6700\u5C0F\u7684\u5A5A\u751F\u5B50\u5973\u3002")}),r("ryman-frey","Ryman Frey","\u8D56\u66FC\xB7\u4F5B\u96F7",{father:"stevron-frey",note:e("Stevron's son; heir after him.","\u53F2\u63D0\u592B\u4F26\u4E4B\u5B50\uFF0C\u5176\u540E\u7684\u7EE7\u627F\u4EBA\u3002"),fate:e("Hanged by the brotherhood without banners in A Feast for Crows.","\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\u88AB\u65E0\u65D7\u5144\u5F1F\u4F1A\u540A\u6B7B\u3002")}),r("edwyn-frey","Edwyn Frey","\u827E\u5FB7\u6E29\xB7\u4F5B\u96F7",{father:"ryman-frey",note:e("Ryman's cold, clever son.","\u8D56\u66FC\u51B7\u9177\u7CBE\u660E\u7684\u513F\u5B50\u3002")}),r("walder-frey-black","Black Walder Frey","\u201C\u9ED1\u201D\u74E6\u5FB7\xB7\u4F5B\u96F7",{father:"ryman-frey",note:e("Ryman's violent son, called Black Walder.","\u8D56\u66FC\u7684\u513F\u5B50\uFF0C\u51F6\u66B4\u597D\u6597\uFF0C\u4EBA\u79F0\u201C\u9ED1\u74E6\u5FB7\u201D\u3002")}),r("petyr-frey","Petyr Frey","\u6D3E\u63D0\u5C14\xB7\u4F5B\u96F7",{father:"ryman-frey",note:e('"Petyr Pimple".',"\u4EBA\u79F0\u201C\u75D8\u75D8\u6D3E\u63D0\u5C14\u201D\u3002"),fate:e("Hanged by the brotherhood after the Red Wedding.","\u8840\u8272\u5A5A\u793C\u540E\u88AB\u5144\u5F1F\u4F1A\u540A\u6B7B\u3002")}),r("aegon-frey-jinglebell","Aegon Frey","\u4F0A\u803F\xB7\u4F5B\u96F7",{father:"aenys-frey",note:e("Simple-minded grandson called Jinglebell.","\u5FC3\u667A\u5982\u5B69\u7AE5\u7684\u5B59\u5B50\uFF0C\u4EBA\u79F0\u201C\u5C0F\u94C3\u94DB\u201D\u3002"),fate:e("Killed by Catelyn at the Red Wedding.","\u5728\u8840\u8272\u5A5A\u793C\u4E0A\u88AB\u51EF\u7279\u7433\u6240\u6740\u3002")}),r("walda-frey","Walda Frey","\u74E6\u59B2\xB7\u4F5B\u96F7",{father:"merrett-frey",mother:"mariya-darry",spouses:["roose-bolton"],note:e(`"Fat Walda", Merrett's daughter; Roose Bolton chose her for her weight in silver.`,"\u4EBA\u79F0\u201C\u80D6\u74E6\u59B2\u201D\uFF0C\u6885\u91CC\u4E4B\u5973\uFF1B\u5362\u65AF\xB7\u6CE2\u987F\u56E0\u80FD\u6309\u4F53\u91CD\u6362\u53D6\u7B49\u91CD\u7684\u767D\u94F6\u800C\u9009\u4E2D\u4E86\u5979\u3002")}),r("walder-frey-little","Little Walder Frey","\u201C\u5C0F\u201D\u74E6\u5FB7\xB7\u4F5B\u96F7",{father:"merrett-frey",mother:"mariya-darry",note:e("Merrett's son, fostered at Winterfell.","\u6885\u91CC\u4E4B\u5B50\uFF0C\u5728\u4E34\u51AC\u57CE\u53D7\u517B\u3002"),fate:e("Found dead at Winterfell in A Dance with Dragons.","\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\u88AB\u53D1\u73B0\u6B7B\u4E8E\u4E34\u51AC\u57CE\u3002")}),r("walder-frey-big","Big Walder Frey","\u201C\u5927\u201D\u74E6\u5FB7\xB7\u4F5B\u96F7",{father:"jammos-frey",note:e("Jammos's son, the sharper of the two Walders fostered at Winterfell.","\u8A79\u59C6\u65AF\u4E4B\u5B50\uFF0C\u5728\u4E34\u51AC\u57CE\u53D7\u517B\u7684\u4E24\u4F4D\u74E6\u5FB7\u4E2D\u8F83\u7CBE\u660E\u7684\u4E00\u4E2A\u3002")})]}),a("whent","House Whent","\u6CB3\u5B89\u5BB6\u65CF","harrenhal","extinct","tully",e("Nine black bats on a golden field","\u91D1\u5E95\u4E0A\u4E5D\u53EA\u9ED1\u8272\u8759\u8760"),["#d6b13c","#1d1d1f"],e("The last old house to hold Harrenhal, granted it after the Lothstons fell. Lord Walter Whent hosted the great tourney at Harrenhal in 281, and the line ends with the elderly Lady Shella.","\u6700\u540E\u4E00\u4E2A\u957F\u671F\u6267\u638C\u8D6B\u4F26\u5821\u7684\u5BB6\u65CF\uFF0C\u5728\u7F57\u65AF\u987F\u5BB6\u65CF\u8D25\u843D\u540E\u53D7\u5C01\u6B64\u57CE\u3002\u74E6\u5C14\u7279\xB7\u6CB3\u5B89\u4F2F\u7235\u66FE\u5728281\u5E74\u4E3E\u529E\u8457\u540D\u7684\u8D6B\u4F26\u5821\u6BD4\u6B66\u5927\u4F1A\uFF0C\u5BB6\u65CF\u8840\u8109\u7EC8\u7ED3\u4E8E\u5E74\u8FC8\u7684\u8C22\u62C9\u592B\u4EBA\u3002"),["agot","asos","twoiaf"],{members:[r("minisa-whent","Minisa Whent","\u7C73\u59AE\u838E\xB7\u6CB3\u5B89",{spouses:["hoster-tully"],note:e("Wife of Hoster Tully, mother of Catelyn, Lysa and Edmure; died young.","\u970D\u65AF\u7279\xB7\u5F92\u5229\u4E4B\u59BB\uFF0C\u51EF\u7279\u7433\u3001\u83B1\u838E\u4E0E\u827E\u5FB7\u6155\u4E4B\u6BCD\uFF0C\u65E9\u901D\u3002")}),r("walter-whent","Walter Whent","\u74E6\u5C14\u7279\xB7\u6CB3\u5B89",{note:e("Lord of Harrenhal who hosted the tourney of 281.","\u8D6B\u4F26\u5821\u4F2F\u7235\uFF0C281\u5E74\u6BD4\u6B66\u5927\u4F1A\u7684\u4E3B\u529E\u8005\u3002")}),r("oswell-whent","Oswell Whent","\u5965\u65AF\u5A01\u5C14\xB7\u6CB3\u5B89",{note:e("Knight of the Kingsguard under Aerys II; Walter's brother.","\u4F0A\u91CC\u65AF\u4E8C\u4E16\u7684\u5FA1\u6797\u94C1\u536B\uFF0C\u74E6\u5C14\u7279\u4E4B\u5F1F\u3002"),fate:e("Falls with Ser Arthur Dayne and Ser Gerold Hightower at the tower of joy.","\u4E0E\u4E9A\u745F\xB7\u6234\u6069\u7235\u58EB\u3001\u6770\u6D1B\xB7\u6D77\u5854\u5C14\u7235\u58EB\u4E00\u540C\u6218\u6B7B\u4E8E\u6781\u4E50\u5854\u3002")}),r("shella-whent","Shella Whent","\u8C22\u62C9\xB7\u6CB3\u5B89",{note:e("Lady of Harrenhal and last of the Whents.","\u8D6B\u4F26\u5821\u5973\u4F2F\u7235\uFF0C\u6CB3\u5B89\u5BB6\u65CF\u7684\u6700\u540E\u4E00\u4EBA\u3002"),fate:e("Harrenhal is taken from her by the Lannisters in A Game of Thrones.","\u300A\u6743\u529B\u7684\u6E38\u620F\u300B\u4E2D\u8D6B\u4F26\u5821\u88AB\u5170\u5C3C\u65AF\u7279\u5BB6\u593A\u8D70\u3002")}),r("sarya-whent","Sarya Whent","\u8428\u4E3D\u96C5\xB7\u6CB3\u5B89",{spouses:["walder-frey"],note:e("Fifth wife of Walder Frey; died childless.","\u74E6\u5FB7\xB7\u4F5B\u96F7\u7684\u7B2C\u4E94\u4EFB\u59BB\u5B50\uFF0C\u65E0\u5B50\u800C\u7EC8\u3002")})]}),a("blackwood","House Blackwood","\u5E03\u83B1\u4F0D\u5FB7\u5BB6\u65CF","raventree-hall","major","tully",e("A flock of ravens around a dead white weirwood, on a scarlet field","\u7329\u7EA2\u5E95\u4E0A\uFF0C\u4E00\u7FA4\u6E21\u9E26\u73AF\u7ED5\u7740\u4E00\u68F5\u67AF\u6B7B\u7684\u767D\u8272\u9C7C\u6881\u6728"),["#8e1f1f","#ece8df"],e("One of the oldest houses of the riverlands, descended from First Men kings and still keeping the old gods. Its feud with the Brackens has lasted thousands of years. Melissa Blackwood was a mistress of Aegon IV and mother of Brynden Rivers.","\u6CB3\u95F4\u5730\u6700\u53E4\u8001\u7684\u5BB6\u65CF\u4E4B\u4E00\uFF0C\u6E90\u81EA\u5148\u6C11\u8BF8\u738B\uFF0C\u81F3\u4ECA\u4FE1\u5949\u65E7\u795E\u3002\u4E0E\u5E03\u96F7\u80AF\u5BB6\u65CF\u7684\u4E16\u4EC7\u5DF2\u5EF6\u7EED\u6570\u5343\u5E74\u3002\u6885\u8389\u838E\xB7\u5E03\u83B1\u4F0D\u5FB7\u66FE\u662F\u4F0A\u803F\u56DB\u4E16\u7684\u60C5\u5987\uFF0C\u5E03\u6797\u767B\xB7\u6CB3\u6587\u4E4B\u6BCD\u3002"),["affc","adwd","twoiaf"],{members:[r("melissa-blackwood","Melissa Blackwood","\u6885\u8389\u838E\xB7\u5E03\u83B1\u4F0D\u5FB7",{note:e('"Missy", a mistress of King Aegon IV and mother of Brynden Rivers (Bloodraven).',"\u6635\u79F0\u201C\u871C\u897F\u201D\uFF0C\u56FD\u738B\u4F0A\u803F\u56DB\u4E16\u7684\u60C5\u5987\uFF0C\u5E03\u6797\u767B\xB7\u6CB3\u6587\uFF08\u8840\u9E26\uFF09\u4E4B\u6BCD\u3002")}),r("alyssa-blackwood","Alyssa Blackwood","\u827E\u4E3D\u838E\xB7\u5E03\u83B1\u4F0D\u5FB7",{spouses:["walder-frey"],note:e("Fourth wife of Walder Frey, mother of Lothar and Jammos.","\u74E6\u5FB7\xB7\u4F5B\u96F7\u7684\u7B2C\u56DB\u4EFB\u59BB\u5B50\uFF0C\u7F57\u7D22\u4E0E\u8A79\u59C6\u65AF\u4E4B\u6BCD\u3002")}),r("tytos-blackwood","Tytos Blackwood","\u6CF0\u9640\u65AF\xB7\u5E03\u83B1\u4F0D\u5FB7",{note:e("Lord of Raventree Hall, a tall, stern lord loyal to Riverrun.","\u9E26\u6811\u57CE\u4F2F\u7235\uFF0C\u9AD8\u5927\u4E25\u8083\uFF0C\u5FE0\u4E8E\u5954\u6D41\u57CE\u3002")}),r("brynden-blackwood","Brynden Blackwood","\u5E03\u6797\u767B\xB7\u5E03\u83B1\u4F0D\u5FB7",{father:"tytos-blackwood",note:e("Tytos's eldest son and heir.","\u6CF0\u9640\u65AF\u7684\u957F\u5B50\u4E0E\u7EE7\u627F\u4EBA\u3002")}),r("lucas-blackwood","Lucas Blackwood","\u5362\u5361\u65AF\xB7\u5E03\u83B1\u4F0D\u5FB7",{father:"tytos-blackwood",note:e("A son of Tytos who rode with Robb Stark.","\u6CF0\u9640\u65AF\u4E4B\u5B50\uFF0C\u8FFD\u968F\u7F57\u67CF\xB7\u53F2\u5854\u514B\u3002"),fate:e("Killed at the Red Wedding.","\u6B7B\u4E8E\u8840\u8272\u5A5A\u793C\u3002")}),r("hoster-blackwood","Hoster Blackwood","\u970D\u65AF\u7279\xB7\u5E03\u83B1\u4F0D\u5FB7",{father:"tytos-blackwood",note:e("A bookish younger son, given to Jaime as a hostage.","\u7231\u8BFB\u4E66\u7684\u5E7C\u5B50\uFF0C\u88AB\u4EA4\u7ED9\u8A79\u59C6\u4F5C\u4EBA\u8D28\u3002")})]}),a("bracken","House Bracken","\u5E03\u96F7\u80AF\u5BB6\u65CF","stone-hedge","major","tully",e("A rearing red stallion on a golden field","\u91D1\u5E95\u4E0A\u4E00\u5339\u4EBA\u7ACB\u7684\u7EA2\u8272\u9A8F\u9A6C"),["#d6b13c","#8e2b1d"],e("Proud lords of Stone Hedge and the Blackwoods' ancient enemies; they claim descent from First Men kings and turned to the Seven long ago. Barba Bracken, a mistress of Aegon IV, bore him Aegor Rivers, called Bittersteel.","\u77F3\u7BF1\u57CE\u9A84\u50B2\u7684\u9886\u4E3B\uFF0C\u5E03\u83B1\u4F0D\u5FB7\u5BB6\u65CF\u7684\u5BBF\u654C\uFF1B\u81EA\u79F0\u6E90\u81EA\u5148\u6C11\u8BF8\u738B\uFF0C\u5F88\u65E9\u4FBF\u6539\u4FE1\u4E03\u795E\u3002\u4F0A\u803F\u56DB\u4E16\u7684\u60C5\u5987\u82AD\u82AD\xB7\u5E03\u96F7\u80AF\u4E3A\u4ED6\u751F\u4E0B\u4E86\u4EBA\u79F0\u201C\u5BD2\u94C1\u201D\u7684\u4F0A\u845B\xB7\u6CB3\u6587\u3002"),["agot","affc","twoiaf"],{members:[r("barba-bracken","Barba Bracken","\u82AD\u82AD\xB7\u5E03\u96F7\u80AF",{note:e("Mistress of Aegon IV and mother of Aegor Rivers (Bittersteel).","\u4F0A\u803F\u56DB\u4E16\u7684\u60C5\u5987\uFF0C\u4F0A\u845B\xB7\u6CB3\u6587\uFF08\u5BD2\u94C1\uFF09\u4E4B\u6BCD\u3002")}),r("jonos-bracken","Jonos Bracken","\u4E54\u8BFA\u65AF\xB7\u5E03\u96F7\u80AF",{note:e("Lord of Stone Hedge; a huge, hot-tempered man who fights for Robb Stark.","\u77F3\u7BF1\u57CE\u4F2F\u7235\uFF0C\u8EAB\u6750\u9B41\u68A7\u3001\u813E\u6C14\u706B\u7206\uFF0C\u4E3A\u7F57\u67CF\xB7\u53F2\u5854\u514B\u4F5C\u6218\u3002"),fate:e("Bends the knee to King Tommen in A Feast for Crows.","\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\u5411\u6258\u66FC\u56FD\u738B\u5C48\u819D\u3002")})]}),a("mallister","House Mallister","\u6885\u5229\u65AF\u7279\u5BB6\u65CF","seagard","major","tully",e("A silver eagle displayed on indigo","\u975B\u84DD\u5E95\u4E0A\u4E00\u53EA\u5C55\u7FC5\u7684\u94F6\u9E70"),["#3a3570","#cfd4dc"],e("Lords of Seagard, guardians of the riverlands coast against the ironborn, known for courtesy and steadfast loyalty to the Tullys.","\u6D77\u7586\u57CE\u9886\u4E3B\uFF0C\u5B88\u62A4\u6CB3\u95F4\u5730\u6D77\u5CB8\u3001\u62B5\u5FA1\u94C1\u79CD\u7684\u5BB6\u65CF\uFF0C\u4EE5\u793C\u6570\u5468\u5168\u548C\u5BF9\u5F92\u5229\u5BB6\u575A\u5B9A\u7684\u5FE0\u8BDA\u8457\u79F0\u3002"),["agot","asos","twoiaf"],{words:e("Above the Rest","\u9AD8\u9AD8\u5728\u4E0A"),members:[r("jason-mallister","Jason Mallister","\u6770\u68EE\xB7\u6885\u5229\u65AF\u7279",{note:e("Lord of Seagard; once fought Rhaegar on the Trident.","\u6D77\u7586\u57CE\u4F2F\u7235\uFF0C\u66FE\u5728\u4E09\u53C9\u621F\u6CB3\u4E0E\u96F7\u52A0\u4EA4\u624B\u3002")}),r("patrek-mallister","Patrek Mallister","\u6D3E\u5D14\u514B\xB7\u6885\u5229\u65AF\u7279",{father:"jason-mallister",note:e("Lord Jason's son and heir, a friend of Theon Greyjoy in Robb's camp.","\u6770\u68EE\u4F2F\u7235\u4E4B\u5B50\u4E0E\u7EE7\u627F\u4EBA\uFF0C\u5728\u7F57\u67CF\u519B\u8425\u4E2D\u4E0E\u5E2D\u6069\xB7\u845B\u96F7\u4E54\u4F0A\u4EA4\u597D\u3002")})]}),a("darry","House Darry","\u6234\u745E\u5BB6\u65CF","darry","major","tully",e("A brown plowman on a green field","\u7EFF\u5E95\u4E0A\u4E00\u540D\u68D5\u8272\u7684\u519C\u592B"),["#3d7a3a","#7a5230"],e("Lords of Darry, long loyal to the Targaryens: Ser Jonothor died in the Kingsguard on the Trident and Ser Willem carried the last Targaryen children into exile.","\u6234\u745E\u57CE\u7684\u9886\u4E3B\uFF0C\u957F\u671F\u5FE0\u4E8E\u5766\u683C\u5229\u5B89\u5BB6\u65CF\uFF1A\u4E54\u65AF\xB7\u6234\u745E\u7235\u58EB\u4F5C\u4E3A\u5FA1\u6797\u94C1\u536B\u6218\u6B7B\u5728\u4E09\u53C9\u621F\u6CB3\uFF0C\u5A01\u5EC9\xB7\u6234\u745E\u7235\u58EB\u5219\u62A4\u9001\u5766\u683C\u5229\u5B89\u5BB6\u6700\u540E\u7684\u5B69\u5B50\u6D41\u4EA1\u6D77\u5916\u3002"),["agot","acok","twoiaf"],{members:[r("jonothor-darry","Jonothor Darry","\u4E54\u65AF\xB7\u6234\u745E",{note:e("Knight of the Kingsguard; fell at the Battle of the Trident.","\u5FA1\u6797\u94C1\u536B\uFF0C\u6218\u6B7B\u4E8E\u4E09\u53C9\u621F\u6CB3\u4E4B\u6218\u3002")}),r("willem-darry","Willem Darry","\u5A01\u5EC9\xB7\u6234\u745E",{note:e("Master-at-arms on Dragonstone who took Viserys and Daenerys to Braavos.","\u9F99\u77F3\u5C9B\u7684\u6B66\u672F\u6559\u5934\uFF0C\u5E26\u97E6\u8D5B\u91CC\u65AF\u4E0E\u4E39\u59AE\u8389\u4E1D\u9003\u5F80\u5E03\u62C9\u4F5B\u65AF\u3002")}),r("raymun-darry","Raymun Darry","\u96F7\u8499\xB7\u6234\u745E",{note:e("Lord of Darry when King Robert visits.","\u52B3\u52C3\u56FD\u738B\u6765\u8BBF\u65F6\u7684\u6234\u745E\u4F2F\u7235\u3002"),fate:e("Killed in the war; his young heir Lyman later dies too.","\u6218\u6B7B\uFF1B\u5176\u5E74\u5E7C\u7684\u7EE7\u627F\u4EBA\u83B1\u66FC\u968F\u540E\u4E5F\u6B7B\u53BB\u3002")}),r("mariya-darry","Mariya Darry","\u739B\u5229\u4E9A\xB7\u6234\u745E",{spouses:["merrett-frey"],note:e("Wife of Merrett Frey.","\u6885\u91CC\xB7\u4F5B\u96F7\u4E4B\u59BB\u3002")})]}),a("mooton","House Mooton","\u6155\u987F\u5BB6\u65CF","maidenpool","major","tully",e("A red salmon on a white field","\u767D\u5E95\u4E0A\u4E00\u6761\u7EA2\u8272\u9C91\u9C7C"),["#ece7de","#c0392b"],e("Lords of Maidenpool on the Bay of Crabs. Lord William Mooton keeps behind his walls through much of the war.","\u8783\u87F9\u6E7E\u7554\u5973\u6CC9\u9547\u7684\u9886\u4E3B\u3002\u6218\u4E89\u5927\u90E8\u5206\u65F6\u95F4\u91CC\uFF0C\u5A01\u5EC9\xB7\u6155\u987F\u4F2F\u7235\u90FD\u95ED\u5B88\u57CE\u4E2D\u3002"),["acok","affc","twoiaf"],{words:e("Wisdom and Strength","\u667A\u6167\u4E0E\u529B\u91CF")}),a("piper","House Piper","\u6D3E\u67CF\u5BB6\u65CF","pinkmaiden","major","tully",e("A dancing maiden in a swirling pink gown, on a blue field","\u84DD\u5E95\u4E0A\u4E00\u4F4D\u8EAB\u7740\u98D8\u821E\u7C89\u8272\u957F\u88D9\u7684\u821E\u5973"),["#3a5ea6","#e89bb5"],e("Lords of Pinkmaiden in the western riverlands. Marq Piper raids the Lannister lines early in the war beside Karyl Vance.","\u6CB3\u95F4\u5730\u897F\u90E8\u7C89\u7EA2\u57CE\u7684\u9886\u4E3B\u3002\u6218\u4E89\u521D\u671F\uFF0C\u9A6C\u67EF\xB7\u6D3E\u67CF\u4E0E\u5361\u5217\u5C14\xB7\u51E1\u65AF\u4E00\u540C\u88AD\u6270\u5170\u5C3C\u65AF\u7279\u519B\u7684\u540E\u65B9\u3002"),["agot","asos","adwd","twoiaf"]),a("vance-of-atranta","House Vance of Atranta","\u963F\u7279\u5170\u5854\u7684\u51E1\u65AF\u5BB6\u65CF","atranta","major","tully",e("Black and white arms (the two Vance branches bear differenced versions)","\u9ED1\u767D\u4E24\u8272\u7EB9\u7AE0\uFF08\u51E1\u65AF\u4E24\u652F\u7EB9\u7AE0\u7565\u6709\u533A\u522B\uFF09"),["#1f1f22","#eceae5"],e("One of the two branches of House Vance; Lord Norbert Vance of Atranta is blind and old.","\u51E1\u65AF\u5BB6\u65CF\u7684\u4E24\u4E2A\u5206\u652F\u4E4B\u4E00\uFF1B\u963F\u7279\u5170\u5854\u7684\u8BFA\u4F2F\u7279\xB7\u51E1\u65AF\u4F2F\u7235\u5E74\u8001\u76EE\u76F2\u3002"),["asos","twoiaf"]),a("vance-of-wayfarers-rest","House Vance of Wayfarer's Rest","\u65C5\u4EBA\u61A9\u57CE\u7684\u51E1\u65AF\u5BB6\u65CF","wayfarers-rest","major","tully",e("Black and white arms (the two Vance branches bear differenced versions)","\u9ED1\u767D\u4E24\u8272\u7EB9\u7AE0\uFF08\u51E1\u65AF\u4E24\u652F\u7EB9\u7AE0\u7565\u6709\u533A\u522B\uFF09"),["#1f1f22","#eceae5"],e("The other branch of House Vance; Karyl Vance succeeds his father as lord during the war.","\u51E1\u65AF\u5BB6\u65CF\u7684\u53E6\u4E00\u5206\u652F\uFF1B\u5361\u5217\u5C14\xB7\u51E1\u65AF\u5728\u6218\u4E89\u4E2D\u7EE7\u627F\u7236\u4EB2\u6210\u4E3A\u9886\u4E3B\u3002"),["agot","asos","twoiaf"]),a("smallwood","House Smallwood","\u65AF\u83AB\u4F0D\u5FB7\u5BB6\u65CF","acorn-hall","minor","tully",e("Six acorns on a yellow field","\u9EC4\u5E95\u4E0A\u516D\u679A\u6A61\u679C"),["#d9c25a","#6b4a25"],e("Lords of Acorn Hall. Lord Theomar Smallwood is away at war when Arya stays with his lady, Ravella.","\u6A61\u679C\u5385\u7684\u9886\u4E3B\u3002\u827E\u8389\u4E9A\u501F\u5BBF\u65F6\uFF0C\u8D5B\u6B27\u739B\xB7\u65AF\u83AB\u4F0D\u5FB7\u4F2F\u7235\u6B63\u5728\u5916\u5F81\u6218\uFF0C\u7531\u4ED6\u7684\u592B\u4EBA\u62C9\u8587\u62C9\u62DB\u5F85\u3002"),["asos","twoiaf"]),a("butterwell","House Butterwell","\u5DF4\u7279\u5A01\u5BB6\u65CF","whitewalls","minor","tully",e("Wavy bands of green, cream and yellow","\u7EFF\u3001\u4E73\u767D\u3001\u9EC4\u4E09\u8272\u6CE2\u7EB9\u6761\u5E26"),["#5b8c4a","#e9d98a"],e("Lords of Whitewalls, a house that lost much after a Blackfyre plot came to light at its castle in the reign of Aegon V.","\u767D\u5899\u57CE\u7684\u9886\u4E3B\u3002\u4F0A\u803F\u4E94\u4E16\u65F6\u671F\uFF0C\u4E00\u573A\u9ED1\u706B\u9634\u8C0B\u5728\u5176\u57CE\u4E2D\u8D25\u9732\uFF0C\u5BB6\u65CF\u7531\u6B64\u5927\u53D7\u6253\u51FB\u3002"),["twoiaf"]),a("ryger","House Ryger","\u83B1\u683C\u5BB6\u65CF","willow-wood","minor","tully",o,t,e("Lords of Willow Wood. Ser Robin Ryger, captain of the guard at Riverrun, comes of this house.","\u67F3\u6797\u57CE\u7684\u9886\u4E3B\u3002\u5954\u6D41\u57CE\u536B\u961F\u961F\u957F\u7F57\u5BBE\xB7\u83B1\u683C\u7235\u58EB\u5373\u51FA\u81EA\u6B64\u5BB6\u3002"),["twoiaf"]),a("cox","House Cox","\u8003\u514B\u65AF\u5BB6\u65CF","saltpans","minor","tully",o,t,e("Holders of the small castle at Saltpans; the aged Ser Quincy Cox keeps his gates shut when the town is sacked.","\u76D0\u573A\u9547\u5C0F\u57CE\u5821\u7684\u4E3B\u4EBA\uFF1B\u5C0F\u9547\u906D\u6D17\u52AB\u65F6\uFF0C\u5E74\u8FC8\u7684\u6606\u897F\xB7\u8003\u514B\u65AF\u7235\u58EB\u7D27\u95ED\u57CE\u95E8\u3002"),["affc"]),a("roote","House Roote","\u9C81\u7279\u5BB6\u65CF","lord-harroways-town","minor","tully",o,t,e("Lords of Lord Harroway's Town, which still bears the name of its earlier, extinct holders.","\u54C8\u7F57\u5A01\u4F2F\u7235\u9547\u7684\u9886\u4E3B\uFF0C\u9547\u540D\u4ECD\u6CBF\u7528\u5176\u65E9\u5DF2\u7EDD\u55E3\u7684\u524D\u4E3B\u4EBA\u4E4B\u540D\u3002"),["asos","twoiaf"]),a("charlton","House Charlton","\u67E5\u5C14\u987F\u5BB6\u65CF",null,"minor","tully",o,t,e("A riverlands house whose lord follows Edmure Tully; little else is told.","\u4E00\u4E2A\u8FFD\u968F\u827E\u5FB7\u6155\xB7\u5F92\u5229\u7684\u6CB3\u95F4\u5BB6\u65CF\uFF0C\u6B64\u5916\u6240\u77E5\u751A\u5C11\u3002"),["agot","asos"]),a("goodbrook","House Goodbrook","\u53E4\u5FB7\u5E03\u9C81\u514B\u5BB6\u65CF",null,"minor","tully",o,t,e("A riverlands house named among the Tully bannermen; its lord fights for Robb Stark.","\u5217\u540D\u4E8E\u5F92\u5229\u5C01\u81E3\u4E4B\u4E2D\u7684\u6CB3\u95F4\u5BB6\u65CF\uFF0C\u5176\u9886\u4E3B\u4E3A\u7F57\u67CF\xB7\u53F2\u5854\u514B\u4F5C\u6218\u3002"),["agot","asos"]),a("haigh","House Haigh","\u6D77\u683C\u5BB6\u65CF",null,"minor","frey",o,t,e("A small house sworn to the Freys; Ser Harys Haigh is among the Frey kin at the Twins.","\u6548\u5FE0\u4F5B\u96F7\u5BB6\u65CF\u7684\u5C0F\u5BB6\u65CF\uFF1B\u54C8\u745E\u65AF\xB7\u6D77\u683C\u7235\u58EB\u662F\u5B6A\u6CB3\u57CE\u4F5B\u96F7\u4EB2\u65CF\u4E2D\u7684\u4E00\u5458\u3002"),["asos","affc"]),a("lychester","House Lychester","\u83B1\u5207\u65AF\u7279\u5BB6\u65CF",null,"minor","tully",o,t,e("A riverlands house sworn to Riverrun; its old lord is said to be failing in mind.","\u6548\u5FE0\u5954\u6D41\u57CE\u7684\u6CB3\u95F4\u5BB6\u65CF\uFF1B\u636E\u8BF4\u5176\u8001\u9886\u4E3B\u5DF2\u795E\u5FD7\u4E0D\u6E05\u3002"),["agot","affc"]),a("paege","House Paege","\u4F69\u683C\u5BB6\u65CF",null,"minor","tully",o,t,e("A riverlands house sworn to Riverrun whose lord answers Edmure's call in the war.","\u6548\u5FE0\u5954\u6D41\u57CE\u7684\u6CB3\u95F4\u5BB6\u65CF\uFF0C\u5176\u9886\u4E3B\u5728\u6218\u4E89\u4E2D\u54CD\u5E94\u827E\u5FB7\u6155\u7684\u53EC\u96C6\u3002"),["asos","affc"]),a("wayn","House Wayn","\u97E6\u6069\u5BB6\u65CF",null,"minor","tully",o,t,e("A minor house of the riverlands; a Wayn serves in Riverrun's household guard.","\u6CB3\u95F4\u5730\u7684\u5C0F\u5BB6\u65CF\uFF1B\u4E00\u540D\u97E6\u6069\u5BB6\u65CF\u6210\u5458\u5728\u5954\u6D41\u57CE\u4EFB\u536B\u961F\u4E4B\u804C\u3002"),["agot","asos"]),a("grell","House Grell","\u845B\u745E\u5C14\u5BB6\u65CF",null,"minor","tully",o,t,e("A minor house of the riverlands, known only from knights in Tully service.","\u6CB3\u95F4\u5730\u7684\u5C0F\u5BB6\u65CF\uFF0C\u4EC5\u89C1\u5176\u9A91\u58EB\u5728\u5954\u6D41\u57CE\u6548\u529B\u3002"),["asos"]),a("hawick","House Hawick","\u970D\u5A01\u514B\u5BB6\u65CF",null,"minor","tully",o,t,e("A minor house of the riverlands; little more is recorded.","\u6CB3\u95F4\u5730\u7684\u5C0F\u5BB6\u65CF\uFF0C\u8BB0\u8F7D\u5BE5\u5BE5\u3002"),["affc"]),a("strong","House Strong","\u65AF\u58EE\u5BB6\u65CF","harrenhal","extinct","tully",o,t,e("Lords of Harrenhal in the time of King Viserys I. Lyonel Strong was Hand of the King, and the house was destroyed during the Dance of the Dragons.","\u97E6\u8D5B\u91CC\u65AF\u4E00\u4E16\u65F6\u671F\u7684\u8D6B\u4F26\u5821\u9886\u4E3B\u3002\u83B1\u6602\u8BFA\xB7\u65AF\u58EE\u66FE\u4EFB\u56FD\u738B\u4E4B\u624B\uFF0C\u5BB6\u65CF\u5728\u201C\u8840\u9F99\u72C2\u821E\u201D\u4E2D\u8986\u706D\u3002"),["twoiaf"]),a("lothston","House Lothston","\u7F57\u65AF\u987F\u5BB6\u65CF","harrenhal","extinct","tully",e("A black bat on a field divided silver and gold","\u94F6\u91D1\u4E24\u5206\u7684\u5E95\u8272\u4E0A\u4E00\u53EA\u9ED1\u8272\u8759\u8760"),["#cfc9b5","#1d1d1f"],e("Held Harrenhal after the Dance of the Dragons until their dark reputation and a rebellion brought them down; Lady Danelle Lothston was rumoured to bathe in blood.","\u201C\u8840\u9F99\u72C2\u821E\u201D\u4E4B\u540E\u6267\u638C\u8D6B\u4F26\u5821\uFF0C\u76F4\u5230\u6076\u540D\u4E0E\u53DB\u4E71\u4EE4\u5176\u8986\u706D\uFF1B\u4F20\u8BF4\u8FBE\u59AE\u62C9\xB7\u7F57\u65AF\u987F\u592B\u4EBA\u7528\u9C9C\u8840\u6C90\u6D74\u3002"),["twoiaf"]),a("qoherys","House Qoherys","\u79D1\u970D\u5229\u65AF\u5BB6\u65CF","harrenhal","extinct","tully",o,t,e("Given Harrenhal by Aegon the Conqueror after Harren's fall; Lord Quenton Qoherys was killed in the early Targaryen reigns, and the line soon failed.","\u8D6B\u4F26\u8D25\u4EA1\u540E\u7531\u5F81\u670D\u8005\u4F0A\u803F\u53D7\u5C01\u8D6B\u4F26\u5821\uFF1B\u6606\u987F\xB7\u79D1\u970D\u5229\u65AF\u4F2F\u7235\u6B7B\u4E8E\u5766\u683C\u5229\u5B89\u738B\u671D\u521D\u5E74\u7684\u53D8\u4E71\uFF0C\u5BB6\u65CF\u4E0D\u4E45\u5373\u544A\u65AD\u7EDD\u3002"),["twoiaf"]),a("harroway","House Harroway","\u54C8\u7F57\u5A01\u5BB6\u65CF","harrenhal","extinct","tully",o,t,e("Lords of Harrenhal briefly under Maegor the Cruel, whose wife Alys was a Harroway; Maegor later had the family slain, leaving only the name of Lord Harroway's Town.","\u5728\u6B8B\u9177\u7684\u6885\u845B\u6CBB\u4E0B\u77ED\u6682\u6267\u638C\u8D6B\u4F26\u5821\uFF0C\u6885\u845B\u7684\u59BB\u5B50\u827E\u4E3D\u4E1D\u5373\u51FA\u81EA\u6B64\u5BB6\uFF1B\u540E\u6765\u6885\u845B\u5C06\u5176\u6EE1\u95E8\u8BDB\u6740\uFF0C\u53EA\u7559\u4E0B\u201C\u54C8\u7F57\u5A01\u4F2F\u7235\u9547\u201D\u8FD9\u4E2A\u5730\u540D\u3002"),["twoiaf"],{otherSeats:["lord-harroways-town"]}),a("hoare","House Hoare","\u970D\u5C14\u5BB6\u65CF","harrenhal","extinct",null,o,["#1d1d1f","#c9a23a"],e("Ironborn kings who conquered the riverlands; Harren the Black built Harrenhal and died in its burning, together with his sons, when Aegon's dragons came.","\u5F81\u670D\u4E86\u6CB3\u95F4\u5730\u7684\u94C1\u79CD\u56FD\u738B\u5BB6\u65CF\uFF1B\u9ED1\u5FC3\u8D6B\u4F26\u5EFA\u8D77\u8D6B\u4F26\u5821\uFF0C\u5E76\u5728\u4F0A\u803F\u7684\u5DE8\u9F99\u6765\u88AD\u65F6\u4E0E\u8BF8\u5B50\u4E00\u540C\u846C\u8EAB\u706B\u6D77\u3002"),["agot","twoiaf"],{members:[r("harren-hoare","Harren Hoare","\u8D6B\u4F26\xB7\u970D\u5C14",{note:e("Harren the Black, King of the Isles and the Rivers; burned in Harrenhal by Aegon's dragons.","\u9ED1\u5FC3\u8D6B\u4F26\uFF0C\u7FA4\u5C9B\u4E0E\u6CB3\u6D41\u4E4B\u738B\uFF0C\u88AB\u4F0A\u803F\u7684\u5DE8\u9F99\u70E7\u6B7B\u5728\u8D6B\u4F26\u5821\u4E2D\u3002")})]}),a("mudd","House Mudd","\u7A46\u5FB7\u5BB6\u65CF","oldstones","extinct",null,o,t,e("First Men kings of the rivers and hills who ruled from Oldstones until the Andals overthrew them; their tombs lie among the ruins.","\u7EDF\u6CBB\u6CB3\u6D41\u4E0E\u5C71\u4E18\u7684\u5148\u6C11\u738B\u65CF\uFF0C\u4EE5\u53E4\u77F3\u57CE\u4E3A\u90FD\uFF0C\u76F4\u5230\u88AB\u5B89\u8FBE\u5C14\u4EBA\u63A8\u7FFB\uFF1B\u5176\u9675\u5893\u4ECD\u5728\u5E9F\u589F\u4E2D\u3002"),["asos","twoiaf"])]};export{g as default};
